        } else {
            currentChar = text.charAt(0);
        }
        if (lastChar != null && currentChar.equals(c) && lastChar.equals(currentChar)) {
            subSequenceLength++;
        } else {
            if (((lastChar != null && !lastChar.equals(currentChar)) || i + 1 == this.getTextElements().size()) && subSequenceLength >= minRunLength) {
